<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 640 330" font-family="system-ui, sans-serif" font-size="15" fill="#1E1C52"><style>.nt{animation:ntin 5s ease-in-out infinite}.nb{animation:nbpulse 5s ease-in-out infinite}@keyframes ntin{0%,12%{opacity:1;transform:none}22%,38%{opacity:0;transform:translateY(8px)}55%,100%{opacity:1;transform:none}}@keyframes nbpulse{0%,20%{stroke-width:2}30%,45%{stroke-width:5}55%,100%{stroke-width:2}}@media (prefers-reduced-motion:reduce){.nt,.nb{animation:none}}</style><defs><marker id="tk" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0 0L10 5L0 10z" fill="#E8590C"/></marker></defs><text x="20" y="28" font-size="14" fill="#5E5B85">Il testo diventa token, e ogni token un numero:</text><rect x="20" y="42" width="48" height="38" rx="9" fill="#DCEBFF" stroke="#2F8CF0" stroke-width="2"/><text x="44.0" y="67" text-anchor="middle" font-size="16" xml:space="preserve">Il</text><text x="44.0" y="100" text-anchor="middle" font-size="13" fill="#5E5B85">1093</text><rect x="74" y="42" width="84" height="38" rx="9" fill="#ECE6FF" stroke="#7048E8" stroke-width="2"/><text x="116.0" y="67" text-anchor="middle" font-size="16" xml:space="preserve"> gatto</text><text x="116.0" y="100" text-anchor="middle" font-size="13" fill="#5E5B85">41822</text><rect x="164" y="42" width="73" height="38" rx="9" fill="#DCEBFF" stroke="#2F8CF0" stroke-width="2"/><text x="200.5" y="67" text-anchor="middle" font-size="16" xml:space="preserve"> sale</text><text x="200.5" y="100" text-anchor="middle" font-size="13" fill="#5E5B85">9134</text><rect x="243" y="42" width="62" height="38" rx="9" fill="#ECE6FF" stroke="#7048E8" stroke-width="2"/><text x="274.0" y="67" text-anchor="middle" font-size="16" xml:space="preserve"> sul</text><text x="274.0" y="100" text-anchor="middle" font-size="13" fill="#5E5B85">1507</text><g class="nt"><rect x="311" y="42" width="73" height="38" rx="9" fill="#FFE8D6" stroke="#E8590C" stroke-width="2" stroke-dasharray="5 3"/><text x="347.5" y="67" text-anchor="middle" font-size="16" font-weight="700" fill="#B84508">tetto</text></g><text x="20" y="146" font-size="14" fill="#5E5B85">Probabilità del prossimo token:</text><text x="110" y="182" text-anchor="end" font-size="15" font-weight="700">tetto</text><rect class="nb" x="120" y="164" width="223.2" height="26" rx="6" fill="#FFE8D6" stroke="#E8590C" stroke-width="2"/><text x="353.2" y="182" font-size="14" fill="#B84508" font-weight="700">62%</text><text x="110" y="218" text-anchor="end" font-size="15" font-weight="400">tavolo</text><rect x="120" y="200" width="75.6" height="26" rx="6" fill="#F1F0F8" stroke="#8A87B0" stroke-width="2"/><text x="205.6" y="218" font-size="14" fill="#4A4775" font-weight="700">21%</text><text x="110" y="254" text-anchor="end" font-size="15" font-weight="400">divano</text><rect x="120" y="236" width="32.4" height="26" rx="6" fill="#F1F0F8" stroke="#8A87B0" stroke-width="2"/><text x="162.4" y="254" font-size="14" fill="#4A4775" font-weight="700">9%</text><text x="110" y="290" text-anchor="end" font-size="15" font-weight="400">…</text><rect x="120" y="272" width="28.8" height="26" rx="6" fill="#F1F0F8" stroke="#8A87B0" stroke-width="2"/><text x="158.8" y="290" font-size="14" fill="#4A4775" font-weight="700">8%</text><path d="M403.2 178 C 560 178, 347.5 150, 347.5 88" fill="none" stroke="#E8590C" stroke-width="2" marker-end="url(#tk)"/><text x="20" y="318" font-size="13" fill="#5E5B85">Scelto il token, lo si aggiunge al testo e si ricomincia: un token alla volta.</text></svg>
SVG;
        return <<<'SVG'
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 640 330" font-family="system-ui, sans-serif" font-size="15" fill="#1E1C52"><style>.nt{animation:ntin 5s ease-in-out infinite}.nb{animation:nbpulse 5s ease-in-out infinite}@keyframes ntin{0%,12%{opacity:1;transform:none}22%,38%{opacity:0;transform:translateY(8px)}55%,100%{opacity:1;transform:none}}@keyframes nbpulse{0%,20%{stroke-width:2}30%,45%{stroke-width:5}55%,100%{stroke-width:2}}@media (prefers-reduced-motion:reduce){.nt,.nb{animation:none}}</style><defs><marker id="tk" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0 0L10 5L0 10z" fill="#E8590C"/></marker></defs><text x="20" y="28" font-size="14" fill="#5E5B85">Text becomes tokens, and each token a number:</text><rect x="20" y="42" width="51" height="38" rx="9" fill="#DCEBFF" stroke="#2F8CF0" stroke-width="2"/><text x="45.5" y="67" text-anchor="middle" font-size="16" xml:space="preserve">The</text><text x="45.5" y="100" text-anchor="middle" font-size="13" fill="#5E5B85">791</text><rect x="77" y="42" width="62" height="38" rx="9" fill="#ECE6FF" stroke="#7048E8" stroke-width="2"/><text x="108.0" y="67" text-anchor="middle" font-size="16" xml:space="preserve"> cat</text><text x="108.0" y="100" text-anchor="middle" font-size="13" fill="#5E5B85">8415</text><rect x="145" y="42" width="95" height="38" rx="9" fill="#DCEBFF" stroke="#2F8CF0" stroke-width="2"/><text x="192.5" y="67" text-anchor="middle" font-size="16" xml:space="preserve"> climbs</text><text x="192.5" y="100" text-anchor="middle" font-size="13" fill="#5E5B85">77729</text><rect x="246" y="42" width="73" height="38" rx="9" fill="#ECE6FF" stroke="#7048E8" stroke-width="2"/><text x="282.5" y="67" text-anchor="middle" font-size="16" xml:space="preserve"> onto</text><text x="282.5" y="100" text-anchor="middle" font-size="13" fill="#5E5B85">8800</text><rect x="325" y="42" width="62" height="38" rx="9" fill="#DCEBFF" stroke="#2F8CF0" stroke-width="2"/><text x="356.0" y="67" text-anchor="middle" font-size="16" xml:space="preserve"> the</text><text x="356.0" y="100" text-anchor="middle" font-size="13" fill="#5E5B85">279</text><g class="nt"><rect x="393" y="42" width="62" height="38" rx="9" fill="#FFE8D6" stroke="#E8590C" stroke-width="2" stroke-dasharray="5 3"/><text x="424.0" y="67" text-anchor="middle" font-size="16" font-weight="700" fill="#B84508">roof</text></g><text x="20" y="146" font-size="14" fill="#5E5B85">Probability of the next token:</text><text x="110" y="182" text-anchor="end" font-size="15" font-weight="700">roof</text><rect class="nb" x="120" y="164" width="223.2" height="26" rx="6" fill="#FFE8D6" stroke="#E8590C" stroke-width="2"/><text x="353.2" y="182" font-size="14" fill="#B84508" font-weight="700">62%</text><text x="110" y="218" text-anchor="end" font-size="15" font-weight="400">table</text><rect x="120" y="200" width="75.6" height="26" rx="6" fill="#F1F0F8" stroke="#8A87B0" stroke-width="2"/><text x="205.6" y="218" font-size="14" fill="#4A4775" font-weight="700">21%</text><text x="110" y="254" text-anchor="end" font-size="15" font-weight="400">sofa</text><rect x="120" y="236" width="32.4" height="26" rx="6" fill="#F1F0F8" stroke="#8A87B0" stroke-width="2"/><text x="162.4" y="254" font-size="14" fill="#4A4775" font-weight="700">9%</text><text x="110" y="290" text-anchor="end" font-size="15" font-weight="400">…</text><rect x="120" y="272" width="28.8" height="26" rx="6" fill="#F1F0F8" stroke="#8A87B0" stroke-width="2"/><text x="158.8" y="290" font-size="14" fill="#4A4775" font-weight="700">8%</text><path d="M403.2 178 C 560 178, 424.0 150, 424.0 88" fill="none" stroke="#E8590C" stroke-width="2" marker-end="url(#tk)"/><text x="20" y="318" font-size="13" fill="#5E5B85">Once a token is chosen, it is appended to the text and the process starts again.</text></svg>
SVG;
    }
}

