dasharray="3 3"/><line x1="150" y1="130" x2="560" y2="250" stroke="#8A87B0" stroke-width="2" stroke-dasharray="3 3"/><text x="20" y="320" font-size="13" fill="#5E5B85">{$note}</text></svg>
