ill="#B84508">{$window}</text><text x="74" y="176" text-anchor="middle" font-size="13" fill="#5E5B85">{$cut}</text><text x="74" y="194" text-anchor="middle" font-size="13" fill="#5E5B85">{$cut2}</text><text x="375.0" y="180" text-anchor="middle" font-size="13" fill="#5E5B85">{$keep}</text><text x="16" y="232" font-size="13" fill="#5E5B85">{$note}</text></svg>
