            Q('c3', L('Qual è il modo più affidabile di scegliere tra due modelli?', 'What is the most reliable way to choose between two models?'), [L('Guardare solo chi è primo in classifica', 'Looking only at who tops the leaderboard'), L('Provarli su un piccolo test con i tuoi esempi', 'Trying them on a small test with your examples'), L('Scegliere quello con il nome più recente', 'Picking the one with the newest name'), L('Prendere sempre il più costoso', 'Always taking the most expensive one')], 1, L('I benchmark misurano compiti generici.', 'Benchmarks measure generic tasks.')),
        ], task('text', L('Scegli un tipo di modello per due casi, una riga ciascuno come `caso: scelta`. Casi: `cartelle cliniche riservate` e `smistare 100.000 ticket`. Scelte: `locale` (o `local`) e `piccolo` (o `small`).', 'Pick a kind of model for two cases, one line each as `case: choice`. Cases: `confidential medical records` and `sort 100,000 tickets`. Choices: `local` and `small`.'), '', [re('(cliniche|medical)[^:\n]*:\s*.*(locale|local|open)', L('I dati riservati restano in locale', 'Confidential data stays local')), re('ticket[^:\n]*:\s*.*(piccolo|small|veloce|fast)', L('Un modello piccolo per il volume', 'A small model for volume'))], '', "cartelle cliniche riservate: locale\nsmistare 100.000 ticket: piccolo"), [
            dMatch(pMatch(), [[L('Modello piccolo', 'Small model'), L('Volume alto, compiti facili', 'High volume, easy tasks')], [L('Modello grande', 'Large model'), L('Compiti difficili', 'Hard tasks')], ['Open-weight', L('Pesi scaricabili', 'Downloadable weights')], ['Benchmark', L('Classifica su compiti generici', 'Ranking on generic tasks')], [L('Contesto ampio', 'Large context'), L('Documenti lunghi', 'Long documents')]], L('Il modello giusto per il compito.', 'The right model for the task.')),
